/// A message.
class MessageInfo {
  /// Message ID, hex.
  final String id;

  /// Conversation ID, hex.
  final String conversation;

  /// The name the viewer sees for the sender here.
  final String sender;

  /// The sender's username.
  final String senderUsername;

  /// Sent by this account (from any of its devices).
  final bool outgoing;

  /// When the sender sent it, by their clock (Unix ms).
  final PlatformInt64 sentAtMs;

  /// The latest text; `None` if deleted or of an unsupported kind.
  final String? body;

  /// Deleted by its sender.
  final bool deleted;

  /// A kind of message this version does not understand.
  final bool unsupported;

  /// Edited at least once.
  final bool edited;

  /// Number of versions, the original included.
  final int versions;

  /// Not yet accepted by the server.
  final bool pending;

  /// The server refused it.
  final bool failed;

  /// Yours, and every other member has it: two ticks.
  final bool delivered;

  /// Yours, and every other member read it: two blue ticks.
  final bool read;

  const MessageInfo({
    required this.id,
    required this.conversation,
    required this.sender,
    required this.senderUsername,
    required this.outgoing,
    required this.sentAtMs,
    this.body,
    required this.deleted,
    required this.unsupported,
    required this.edited,
    required this.versions,
    required this.pending,
    required this.failed,
    required this.delivered,
    required this.read,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      conversation.hashCode ^
      sender.hashCode ^
      senderUsername.hashCode ^
      outgoing.hashCode ^
      sentAtMs.hashCode ^
      body.hashCode ^
      deleted.hashCode ^
      unsupported.hashCode ^
      edited.hashCode ^
      versions.hashCode ^
      pending.hashCode ^
      failed.hashCode ^
      delivered.hashCode ^
      read.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is MessageInfo &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          conversation == other.conversation &&
          sender == other.sender &&
          senderUsername == other.senderUsername &&
          outgoing == other.outgoing &&
          sentAtMs == other.sentAtMs &&
          body == other.body &&
          deleted == other.deleted &&
          unsupported == other.unsupported &&
          edited == other.edited &&
          versions == other.versions &&
          pending == other.pending &&
          failed == other.failed &&
          delivered == other.delivered &&
          read == other.read;
}

