      mentions.hashCode ^
      hasLink.hashCode ^
      afterMs.hashCode ^
      beforeMs.hashCode ^
      oldestFirst.hashCode ^
      limit.hashCode ^
      offset.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SearchOptions &&
          runtimeType == other.runtimeType &&
          text == other.text &&
          conversation == other.conversation &&
          from == other.from &&
          mentions == other.mentions &&
          hasLink == other.hasLink &&
          afterMs == other.afterMs &&
          beforeMs == other.beforeMs &&
          oldestFirst == other.oldestFirst &&
          limit == other.limit &&
          offset == other.offset;
}

/// A newer release of the app, checked against the release key.
class UpdateInfo {
  /// Its version.
  final String version;

  /// What changed, as plain text.
  final String notes;

  /// When it was released (Unix ms).
  final PlatformInt64 releasedAtMs;

  /// How much there is to download, in bytes.
  final BigInt size;

  /// This app is too old to keep talking to the server once it updates:
  /// show it prominently. (Not `required`, a word Dart keeps for itself.)
  final bool mandatory;

  /// The app can install it itself: it runs from a release's install,
  /// which updates replace. A copy built from source never installs or
  /// registers itself; it can only say an update exists.
  final bool canInstall;

  const UpdateInfo({
    required this.version,
    required this.notes,
    required this.releasedAtMs,
    required this.size,
    required this.mandatory,
    required this.canInstall,
  });

  @override
  int get hashCode =>
      version.hashCode ^
      notes.hashCode ^
      releasedAtMs.hashCode ^
      size.hashCode ^
      mandatory.hashCode ^
      canInstall.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UpdateInfo &&
          runtimeType == other.runtimeType &&
          version == other.version &&
          notes == other.notes &&
          releasedAtMs == other.releasedAtMs &&
          size == other.size &&
          mandatory == other.mandatory &&
          canInstall == other.canInstall;
}

